using System.Diagnostics.CodeAnalysis;
using Maran.Sdk.Contracts;

namespace Maran.Host.Modules;

/// <summary>
/// The one document a module frame is given, generated by the panel and never read from a package: a
/// page with no inline script or style whose only content is a classic script element for the module's
/// entry file, pinned by its Subresource Integrity value. Because the document is the panel's, a package
/// cannot make its frame load anything but the single script the signed package vouches for.
/// </summary>
public static class ModuleFrameDocument
{
    /// <summary>The prefix every integrity value this document accepts starts with.</summary>
    private const string IntegrityPrefix = "sha384-";

    /// <summary>The length of a SHA-384 digest in base64, padding included.</summary>
    private const int DigestBase64Length = 64;

    /// <summary>Renders the document for a module's screen bundle.</summary>
    /// <param name="description">The bundle's description; its entry and integrity are written into attributes, so both are checked first.</param>
    /// <param name="html">The document, when the description is well-formed.</param>
    /// <returns>True when the entry is a plain script file name and the integrity value is a SHA-384 digest.</returns>
    public static bool TryRender(ModuleSpaDescription description, [NotNullWhen(true)] out string? html)
    {
        ArgumentNullException.ThrowIfNull(description);

        html = null;

        if (!ModuleFramePathRule.IsServableFileName(description.Entry)
            || ModuleFramePathRule.ContentTypeOf(description.Entry) != "text/javascript"
            || !IsSha384Integrity(description.Integrity))
        {
            return false;
        }

        // Nothing here is encoded because nothing here can need it: the entry holds letters, digits and
        // . _ - only (ModuleFramePathRule) and the integrity value holds base64 characters only.
        html = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><title>module</title></head><body>"
            + $"<script src=\"{description.Entry}\" integrity=\"{description.Integrity}\" crossorigin=\"anonymous\"></script>"
            + "</body></html>";
        return true;
    }

    /// <summary>Whether a value is <c>sha384-</c> followed by exactly the base64 of a 48-byte digest.</summary>
    /// <param name="integrity">The value to check.</param>
    /// <returns>True when it is one well-formed SHA-384 integrity value.</returns>
    private static bool IsSha384Integrity(string? integrity)
    {
        if (integrity is null
            || !integrity.StartsWith(IntegrityPrefix, StringComparison.Ordinal)
            || integrity.Length != IntegrityPrefix.Length + DigestBase64Length)
        {
            return false;
        }

        var digest = integrity[IntegrityPrefix.Length..];
        Span<byte> decoded = stackalloc byte[48];

        return Convert.TryFromBase64String(digest, decoded, out var written) && written == decoded.Length;
    }
}
